ssh -o BatchMode=yes user@x.x.x.x 'for c in metapulse-web-1 metapulse-worker-1 metapulse-postgres-1 metapulse-redis-1; do echo "=== $c ==="; docker inspect -f "Ports(HostConfig.PortBindings): {{json .HostConfig.PortBindings}}
ExposedPorts: {{json .Config.ExposedPorts}}
NetworkMode: {{.HostConfig.NetworkMode}}
Networks: {{range \$k,\$v := .NetworkSettings.Networks}}{{\$k}}(aliases={{\$v.Aliases}}) {{end}}
