ssh -o BatchMode=yes user@x.x.x.x 'python3 - <<"PY"
import subprocess
st={"01":"ESTAB","02":"SYN_SENT","03":"SYN_RECV","06":"TIME_WAIT","0A":"LISTEN","08":"CLOSE_WAIT"}
def dec(hp):
    h,p=hp.split(":")
    return ".".join(str(int(h[i:i+2],16)) for i in (6,4,2,0))+":"+str(int(p,16))
for c in ["metapulse-web-1","metapulse-worker-1"]:
    out=subprocess.run(["docker","exec",c,"cat","/proc/net/tcp"],capture_output=True,text=True).stdout
    print("=== "+c+" ===")
    for line in out.splitlines()[1:]:
        f=line.split()
        print(f"  local={dec(f[1]):22} remote={dec(f[2]):22} state={st.get(f[3].upper(),f[3])}")
PY'
